(function(root){
const tokens=['bg','sidebar','panel','raised','hover','border','text','strong','muted','subtle','accent','accent-bg','purple'];
const permissions=['note:read','note:write','workspace:read','ui:panel','storage'];
function theme(value){if(value?.format!=='amago-theme-v1'||typeof value.name!=='string'||!value.name.trim()||value.name.length>60)throw Error('Tema inválido: use o formato amago-theme-v1.');const colors={};for(const key of tokens){if(!/^#[0-9a-f]{6}$/i.test(value.colors?.[key]||''))throw Error('O tema precisa de uma cor hexadecimal de 6 dígitos para '+key+'.');colors[key]=value.colors[key]}return {format:value.format,id:String(value.id||value.name).replace(/[^a-z0-9-]/gi,'-').slice(0,60),name:value.name,author:String(value.author||'Comunidade').slice(0,80),mode:value.mode==='light'?'light':'dark',colors}}
function settingValue(field,value){switch(field.type){case'boolean':if(typeof value!=='boolean')throw Error('Use verdadeiro ou falso.');break;case'number':if(typeof value!=='number'||!Number.isFinite(value)||value<field.min||value>field.max)throw Error('Número fora dos limites.');break;case'select':if(!field.options.includes(value))throw Error('Opção inválida.');break;default:if(typeof value!=='string'||value.length>2000)throw Error('Texto inválido.')}return value}
function settings(schema){if(!Array.isArray(schema)||schema.length>20)throw Error('Declare até 20 configurações.');const seen=new Set();return schema.map(f=>{if(!f||!/^[a-z][a-z0-9_-]{0,39}$/.test(f.key)||['__proto__','constructor','prototype'].includes(f.key)||seen.has(f.key)||typeof f.label!=='string'||!f.label.trim()||f.label.length>80||!['text','number','boolean','select'].includes(f.type))throw Error('Configuração de plugin inválida.');seen.add(f.key);const field={key:f.key,label:f.label,type:f.type,min:Number.isFinite(f.min)?f.min:-1e9,max:Number.isFinite(f.max)?f.max:1e9};if(f.type==='select'){if(!Array.isArray(f.options)||!f.options.length||f.options.length>30||f.options.some(x=>typeof x!=='string'||x.length>80))throw Error('Opções inválidas.');field.options=f.options}field.default=settingValue(field,f.default??(f.type==='boolean'?false:f.type==='number'?Math.max(field.min,Math.min(field.max,0)):f.type==='select'?field.options[0]:''));return field})}
function settingsValues(plugin,values={}){const out={};for(const field of plugin.settings||[])out[field.key]=settingValue(field,Object.hasOwn(values,field.key)?values[field.key]:field.default);return out}
function plugin(value){if(!['amago-plugin-v1','amago-plugin-v2'].includes(value?.format)||!/^[a-z0-9][a-z0-9-]{1,59}$/.test(value.id||'')||typeof value.name!=='string'||!value.name.trim()||value.name.length>80)throw Error('Pacote de plugin inválido.');if(typeof value.code!=='string'||value.code.length>200000)throw Error('O módulo do plugin deve ter até 200 KB.');if(!Array.isArray(value.permissions)||value.permissions.some(p=>!permissions.includes(p)))throw Error('Permissão não suportada.');if(!Array.isArray(value.commands)||!value.commands.length||value.commands.length>24||value.commands.some(c=>!/^[a-z0-9-]{1,40}$/.test(c.id)||typeof c.title!=='string'||!c.title||c.title.length>80)||new Set(value.commands.map(c=>c.id)).size!==value.commands.length)throw Error('Declare de 1 a 24 comandos com identificadores únicos.');const toolbar=value.toolbar||[];if(!Array.isArray(toolbar)||toolbar.length>4||toolbar.some(id=>!value.commands.some(c=>c.id===id)))throw Error('A barra deve referenciar até quatro comandos declarados.');return {format:value.format,id:value.id,name:value.name,version:String(value.version||'1.0.0').slice(0,30),description:String(value.description||'').slice(0,500),author:String(value.author||'Comunidade').slice(0,80),permissions:[...new Set(value.permissions)],commands:value.commands.map(c=>({id:c.id,title:c.title})),settings:settings(value.settings||[]),toolbar:[...new Set(toolbar)],code:value.code,enabled:false}}
root.AmagoExtensions={tokens,theme,plugin,settingsValues,settingValue,permissions};
})(globalThis);
